    assert (
        not claims.loc[claims["claim"].str.contains("CATE policy value"), "allowed"]
        .astype(bool)
        .any()
    )
    assert (
        not claims.loc[claims["claim"].str.contains("fair-lending legal"), "allowed"]
        .astype(bool)
        .any()
    )


